/**
 * 收货人信息解析夹具。
 *
 * 结构与两份真实顺联航账单的 Y 列（收货人信息）逐行同形：门牌连字符、`之`、巷弄鄰、`附1`、
 * 括号备注、`1.5km` 里程、空格 + 地标、繁简混用、公司/人名连接形式、多号码分隔符都保留；
 * **姓名、电话、地址内容全部替换为测试文本**（地址里的地名统一换成「範例」，号码只保留
 * 决定形态的前三位、其余置 0），不携带任何真实客户信息。
 *
 * 生成方式：对真实行先跑一遍解析确定字段边界，再按边界做同形替换，最后**重新解析替换后的
 * 文本并比对结构（字段类型、号码个数、字段是否为空）**，不一致的行不入库——两轮比对结果为
 * 78/78 全部一致。
 */
export interface SlhBillRecipientFixture {
  /** 脱敏后的 Y 列原文。 */
  raw: string
  /** 期望的客户姓名；空串表示期望为 null。 */
  name: string
  /** 期望的客户电话（原文区间）；空串表示期望为 null。 */
  phones: string
  /** 期望的收件地址；空串表示期望为 null。 */
  address: string
}

